// 8x8 black PNG, embedded so the template bytes do not depend on the
// platform's PNG encoder (package:image's zlib differs VM vs web).
const _iconPngBase64 =
    'iVBORw0KGgoAAAANSUhEUgAAAAgAAAAICAIAAABLbSncAAAAD0lEQVR4nGNhwAFYhpYEAA7YACES0d1fAAAAAElFTkSuQmCC';

/// Builds a minimal, realistic template APK in memory (pure Dart, no dart:io).
Uint8List buildMiniTemplate() {
  final icon = base64.decode(_iconPngBase64);
  return writeZip([
    ZipEntry.deflated(kManifestPath, base64.decode(_manifestBase64)),
    ZipEntry.deflated(
      kConfigPath,
      Uint8List.fromList(
        utf8.encode(
          '{"url":"","title":"","color":"#000000","fullscreen":false}',
        ),
      ),
    ),
    for (final d in kIconSizes.keys)
      ZipEntry.stored('res/mipmap-$d-v4/ic_launcher.png', icon),
    ZipEntry.stored('resources.arsc', Uint8List.fromList(List.filled(64, 7))),
  ]);
}
